mapper.insert:
INSERT INTO test_case_folder (project_id, parent_folder_id, name, sort_order)
VALUES (#{projectId}, #{parentFolderId}, #{name},
        (SELECT COALESCE(MAX(sort_order), 0) + 1 FROM test_case_folder
          WHERE project_id = #{projectId}

              AND parent_folder_id = #{parentFolderId}
              AND parent_folder_id IS NULL
          ))

